from PIL import Image
import numpy as np, collections
img = np.array(Image.open('radiograph.jpg').convert('L'), dtype=np.uint8)
h,w = img.shape
bright = (img > 225).astype(np.uint8)
H,W = h//4, w//4
bm = bright[:H*4,:W*4].reshape(H,4,W,4).max(axis=(1,3))
# map labels to ints
lab_id = {}
def getid(t):
    if t not in lab_id: lab_id[t]=len(lab_id)
    return lab_id[t]
parent=[]
def find(a):
    r=a
    while parent[r]!=r: r=parent[r]
    while parent[a]!=r: parent[a],a=r,parent[a]
    return r
def union(a,b):
    ra,rb=find(a),find(b)
    if ra!=rb: parent[max(ra,rb)]=min(ra,rb)
comps = {}
for y in range(H):
    xs = np.nonzero(bm[y])[0]
    if len(xs)==0:
        comps[y]=[]; continue
    breaks = np.nonzero(np.diff(xs)>1)[0]
    segs = np.split(xs, breaks+1)
    prevsegs = comps.get(y-1, [])
    cur=[]
    for seg in segs:
        s,e = int(seg[0]), int(seg[-1])
        overl = [l for (ps,pe,l) in prevsegs if not (pe < s-1 or ps > e+1)]
        if overl:
            l0 = find(overl[0])
            for l in overl[1:]: union(l0,l)
            lab=l0
        else:
            lab = getid((y,s)); parent.append(lab)
        cur.append((s,e,lab))
    comps[y]=cur
groups = collections.defaultdict(lambda: [0,1e9,1e9,-1,-1])
for y,segs in comps.items():
    for (s,e,lab) in segs:
        r = find(lab)
        g = groups[r]
        g[0]+= e-s+1
        g[1]=min(g[1],s); g[2]=min(g[2],y)
        g[3]=max(g[3],e); g[4]=max(g[4],y)
for r,g in sorted(groups.items(), key=lambda kv:-kv[1][0]):
    size, x1,y1,x2,y2 = g
    if size >= 15:
        print(f'size~{size*16}  bbox orig=({x1*4},{y1*4})-({x2*4+4},{y2*4+4})')
